import clsx from "clsx";
import { useId, useState } from "react";
import type { Endpoint } from "../../model/endpoints";
import type {
  ThumbnailOverlayLoadingPreviewRenderer,
  ThumbnailOverlayNowPlayingRenderer,
  ThumbnailOverlayTimeStatusRenderer,
  ThumbnailOverlayToggleButtonRenderer,
} from "../../model/innertube.gen";
import { getText, accessibilityLabel } from "../../model/text";
import { EndpointLink } from "../text/EndpointLink";
import { Image } from "../image/Image";
import type { ThumbnailSet } from "../image/thumbnails";
import { BadgeShape } from "../badge/BadgeShape";
import { Icon } from "../icon/Icon";
import { Tooltip } from "../feedback/Tooltip";
import styles from "./Thumbnail.module.css";

export interface ThumbnailOverlay {
  thumbnailOverlayTimeStatusRenderer?: ThumbnailOverlayTimeStatusRenderer;
  thumbnailOverlayNowPlayingRenderer?: ThumbnailOverlayNowPlayingRenderer;
  thumbnailOverlayToggleButtonRenderer?: ThumbnailOverlayToggleButtonRenderer;
  thumbnailOverlayLoadingPreviewRenderer?: ThumbnailOverlayLoadingPreviewRenderer;
}

export interface ThumbnailProps {
  thumbnail: ThumbnailSet | undefined;
  endpoint: Endpoint | undefined;
  overlays?: ThumbnailOverlay[];
  width: number;
  nowPlaying?: boolean;
  className?: string;
}

function TimeStatus({ data }: { data: ThumbnailOverlayTimeStatusRenderer }) {
  const live = data.style === "LIVE";
  return (
    <div className={styles.timeStatus}>
      <div className={styles.badgeShape}>
        <BadgeShape
          text={getText(data.text)}
          icon={data.icon?.iconType}
          badgeStyle={live ? "live" : "thumbnail"}
          label={accessibilityLabel(data.text as { accessibility?: { accessibilityData?: { label?: string } } })}
        />
      </div>
    </div>
  );
}

function NowPlaying({ data }: { data: ThumbnailOverlayNowPlayingRenderer }) {
  return (
    <div className={styles.nowPlaying}>
      <span className={styles.nowPlayingText}>{getText(data.text)}</span>
      <svg className={styles.equalizer} viewBox="0 0 55 95" aria-hidden="true">
        <g>
          <rect className={styles.bar} x="0" />
          <rect className={styles.bar} x="20" />
          <rect className={styles.bar} x="40" />
        </g>
      </svg>
    </div>
  );
}

function ToggleButton({ data }: { data: ThumbnailOverlayToggleButtonRenderer }) {
  const [toggled, setToggled] = useState(!!data.isToggled);
  const tooltipId = useId();
  const tooltip = toggled ? data.toggledTooltip : data.untoggledTooltip;
  const label = accessibilityLabel((toggled ? data.toggledAccessibility : data.untoggledAccessibility) as { accessibilityData?: { label?: string } });
  return (
    <div className={styles.toggle}>
      <button
        type="button"
        className={styles.toggleButton}
        aria-label={label}
        aria-pressed={toggled}
        aria-describedby={tooltip ? tooltipId : undefined}
        onClick={() => setToggled((t) => !t)}
      >
        <Icon icon={(toggled ? data.toggledIcon : data.untoggledIcon).iconType} />
      </button>
      <Tooltip text={tooltip} id={tooltipId} position="top" />
    </div>
  );
}

function LoadingPreview({ data }: { data: ThumbnailOverlayLoadingPreviewRenderer }) {
  return <div className={styles.loadingPreview}>{getText(data.text)}</div>;
}

/**
 * A video thumbnail with its overlays: duration badges and the now-playing
 * equalizer always, the watch-later toggle and loading hint while hovered.
 */
export function Thumbnail({ thumbnail, endpoint, overlays = [], width, nowPlaying, className }: ThumbnailProps) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      className={clsx(styles.thumbnail, nowPlaying && styles.isNowPlaying, className)}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <EndpointLink endpoint={endpoint} className={styles.link} tabIndex={-1} aria-hidden="true">
        <Image image={thumbnail} width={width} />
        <div className={styles.overlays}>
          {overlays.map((o, i) =>
            o.thumbnailOverlayTimeStatusRenderer ? (
              <TimeStatus key={i} data={o.thumbnailOverlayTimeStatusRenderer} />
            ) : o.thumbnailOverlayNowPlayingRenderer ? (
              <NowPlaying key={i} data={o.thumbnailOverlayNowPlayingRenderer} />
            ) : null,
          )}
        </div>
        <div className={styles.mouseoverOverlay} />
      </EndpointLink>
      <div className={styles.hoverOverlays}>
        {hovered &&
          overlays.map((o, i) =>
            o.thumbnailOverlayToggleButtonRenderer ? (
              <ToggleButton key={i} data={o.thumbnailOverlayToggleButtonRenderer} />
            ) : o.thumbnailOverlayLoadingPreviewRenderer ? (
              <LoadingPreview key={i} data={o.thumbnailOverlayLoadingPreviewRenderer} />
            ) : null,
          )}
      </div>
    </div>
  );
}
